function getMatchingEntries(obj, searchKey) {
    // Split the searchKey into individual keys based on dots.
    const keys = searchKey.split('.');

    let currentObj = obj;
    for (let i = 0; i < keys.length - 1; i++) {
        if (!currentObj || typeof currentObj !== 'object') {
            throw new Error(`Invalid object or not found: ${searchKey}`);
        }
        currentObj = currentObj[keys[i]];
    }

    if (typeof currentObj !== 'object' || currentObj === null) {
        throw new Error(`Not found: ${searchKey}`);
    }

    // Return all matching properties.
    return Object.entries(currentObj).reduce((acc, [key, val]) => {
        if (val.toString() === searchKey) {
            acc.push({ key, value: val });
        }
        return acc;
    }, []);
}

